// Deterministic documentation fixtures. No API, storage or live clock.
(() => {
'use strict';
const states=['check-in-mandatory','check-in-optional','no-admitted','checking-in','checked-in-toast','undo','check-in-failed','check-in-conflict','cancelled-checked-in','team-check-in','check-in-locked'];
const query=new URLSearchParams(location.search);
const state=states.includes(query.get('state'))?query.get('state'):'check-in-mandatory';
document.body.dataset.state=state;
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(type='info')=>`<svg class="fl-icon" viewBox="0 0 24 24" aria-hidden="true">${({info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',error:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 3v1"/>',down:'<path d="m7 10 5 5 5-5"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',switch:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>'})[type]}</svg>`;
const button=(label,action='',cls='',attrs='')=>`<button type="button" class="${cls}" ${action?`data-action="${action}"`:''} ${attrs}>${label}</button>`;
const notice=(heading,text,tone='info',extra='')=>`<section class="fl-notice ${tone}" role="${tone==='danger'?'alert':'status'}">${icon(tone==='danger'?'error':'info')}<div><strong>${heading}</strong><p>${text}</p>${extra}</div></section>`;

const teams=state==='team-check-in', config=state==='check-in-locked';
const title=teams?'Saturday Team League':'Saturday Open';
const zone='Europe/Madrid';
const names=teams?['River Falcons','Team A']:['Robin Vale','Sam Reed','Jamie Brook','Taylor Finch'];
let confirmed=teams?[true,false]:[true,true,state==='checked-in-toast',false];
if(state==='undo')confirmed[0]=false;
let failure=state==='check-in-failed', conflict=state==='check-in-conflict';
if(conflict)confirmed[2]=true;
const empty=state==='no-admitted';
const busy=state==='checking-in';
const labels='<div class="labels" aria-label="Tournament lifecycle"><span>Published</span><span>Registration open</span><span>Preparing</span></div>';
function heading(){return `<header class="fl-heading"><a class="back" href="${config?'entries-states.html?state=list-with-entries':'?state=check-in-locked'}">Back to ${config?'tournaments':'configuration'}</a><div class="title"><h1>${config?'':'Entries · '}${title}</h1>${labels}</div><p class="lead">Example strategy · Standard variant · ${teams?'Team':'Individual'} · Madrid</p><p class="lead">${teams?'28':'21'} November 2026, 10:00 · ${zone}</p></header>`;}
const badge=checked=>`<span class="check-label ${checked?'confirmed':''}">${checked?'Checked in':'Check-in pending'}</span>`;
function row(name,i){const checked=confirmed[i],working=busy&&i===2;return `<li data-entry="${i}" ${working?'aria-busy="true"':''}><div class="entry-copy"><div class="team-identity"><h3>${name}</h3>${badge(checked)}${teams?`<span class="readiness ${i===0?'incomplete':''}">${i===0?'2 of 3–5 players · incomplete':'4 of 3–5 players'}</span>`:''}</div><p class="help">Admitted</p>${checked?`<p class="help">Checked in 12 November 2026, ${i===0?'10:42':i===1?'10:44':'10:46'} · ${zone}</p>`:''}${failure&&i===2?'<p class="row-error" role="alert">Check-in was not recorded. The request failed. Nothing changed; try “Check in” again.</p>':''}${working?'<p class="help" role="status">Checking in. Please wait; do not submit again.</p>':''}</div><div class="row-actions">${teams?button('Roster','roster','',`data-index="${i}" aria-label="Roster: ${name}"`):''}${button(working?'Checking in…':checked?'Undo check-in':'Check in','check','',`data-index="${i}" aria-label="${working?'Checking in':checked?'Undo check-in':'Check in'}: ${name}" ${working||conflict?'disabled':''}`)}${button('Cancel entry','cancel','',`data-index="${i}" aria-label="Cancel entry: ${name}" ${working||conflict?'disabled':''}`)}</div></li>`;}
function entries(){const count=empty?0:names.length,n=empty?0:confirmed.filter(Boolean).length;return `<div class="column"><section class="fl-summary" aria-labelledby="summary-heading"><div><h2 id="summary-heading">${count} of 4 ${teams?'teams':'individual entries'}</h2><p class="help">Automatic admission · ${empty||teams?'0':'1'} waiting for a slot</p><p class="help" id="check-count">Check-in ${state==='check-in-optional'?'optional':'mandatory'}${count?` · ${n} of ${count} checked in`:''}</p><p class="help">Entry terms updated 11 November 2026, 18:00 · ${zone}</p></div>${button(teams?'Add team':'Add player','add','primary')}</section>${conflict?notice('This entry changed elsewhere','Nothing changed with this request. Reload the latest entries before trying again.','danger',`<div class="actions">${button('Reload latest','reload')}</div>`):''}<section class="fl-group"><h2>Admitted · ${count}</h2>${empty?'<p class="help">No admitted entries.</p>':`<ul class="fl-rows">${names.map(row).join('')}</ul>`}</section><section class="fl-group"><h2>Waiting · ${empty||teams?0:1}</h2>${empty||teams?'<p class="help">No waiting entries.</p>':`<ol class="fl-rows"><li><div><h3>1. ${teams?'Meadow Foxes':'Rowan Lake'}</h3><p class="help">Capacity full · Waiting since 12 November 2026, 10:20 · ${zone}</p><p class="help" id="admit-why">No free slot. Cancel an admitted entry or increase capacity.</p></div><div class="row-actions">${teams?button('Roster','roster','','data-index="2" aria-label="Roster: Meadow Foxes"'):''}${button('Admit','','','disabled aria-describedby="admit-why"')}${button('Cancel entry','cancel','','data-index="waiting"')}</div></li></ol>`}</section>${empty?'':`<details class="fl-history" id="cancelled" ${state==='cancelled-checked-in'?'open':''}><summary>Cancelled · 1</summary><ul><li><div class="team-identity"><strong>${teams?'Harbour Lights':'Parker Snow'}</strong>${state==='cancelled-checked-in'?badge(true):''}</div><p class="help">Cancelled 12 November 2026, 10:50 · ${zone}</p>${state==='cancelled-checked-in'?`<p class="help">Checked in 12 November 2026, 10:35 · ${zone} · Read-only</p>`:''}</li></ul></details>`}</div>`;}
function field(name,label,value,help,kind='text',locked=false,wide=false){return `<div class="fl-field ${wide?'wide':''}"><label for="t-${name}">${label}</label>${kind==='select'?`<select id="t-${name}" ${locked?'disabled':''} aria-describedby="t-${name}-help"><option>${value}</option>${locked?'':`<option>${name==='checkIn'?'Optional':name==='visibility'?'Unlisted':'Online'}</option>`}</select>`:`<input id="t-${name}" type="${kind==='readonly'?'text':kind}" value="${value}" ${kind==='readonly'?'readonly':''} aria-describedby="t-${name}-help">`}<p class="help" id="t-${name}-help">${help}</p>${kind==='datetime-local'?`<p class="written">${Number(value.slice(8,10))} November 2026, ${value.slice(11)} · ${zone}</p>`:''}</div>`;}
function configuration(){const lock='Locked while the tournament has entries. Cancel every entry to change it.';const section=(name,help,fields)=>`<fieldset><legend>${name}</legend><p class="help">${help}</p><div class="config-fields">${fields.join('')}</div></fieldset>`;return `<div class="column">${notice('Published · configuration remains editable','Competition is preparing. Saving configuration does not change registration.')}<section class="fl-panel registration"><h2>Registration</h2><p><strong>Registration open</strong></p><dl><div><dt>Announced opening</dt><dd>10 November 2026, 09:00</dd></div><div><dt>Announced closure</dt><dd>13 November 2026, 18:00</dd></div><div class="wide"><dt>Reference time zone</dt><dd>${zone}</dd></div></dl><p class="help">These dates are an announcement. Registration changes only with the action below, not automatically at these times.</p><p>Opened 11 November 2026, 09:30 · ${zone}</p>${button('Close registration','registration','primary')}</section><section class="fl-panel fl-summary"><div><h2>Entries</h2><p>4 of 4 individual entries admitted · 1 waiting</p></div><a class="button" href="?state=check-in-mandatory">View entries</a></section><form class="fl-panel" id="configuration">${section('Tournament details','A published tournament must stay complete.',[
field('title','Title','Saturday Open','The tournament name shown when published.','text',false,true),field('gameVariant','Game / variant','Example strategy · Standard variant','Free text, for example the game and its variant.','text',false,true),field('entryKind','Entry kind','Individual',lock,'select',true),field('capacity','Capacity in individual entries','4','How many entries the tournament admits. At least 4: the admitted entries.','number')])}${section('Competition profile','This H1 profile is fixed; points are not edited per tournament.',[field('profile','Competition profile','Single round-robin · 3 / 1 / 0','Win 3 · Draw 1 · Loss 0. Equal points share a position. Draws are allowed.','readonly',false,true)])}${section('Dates and location','All three times use the reference time zone. A planned date does not start competition.',[
field('registrationOpensAt','Registration opening','2026-11-10T09:00','Planned opening; publication does not open registration.','datetime-local'),field('registrationClosesAt','Registration closure','2026-11-13T18:00','Must not be later than the planned start.','datetime-local'),field('plannedStartAt','Planned start','2026-11-21T10:00','The announced start date and time.','datetime-local'),field('timeZone','Reference time zone',zone,'Times above are interpreted in this zone.','select'),field('location','Location mode','On-site venue','Choose a venue or an online tournament.','select'),field('venue','Venue','Madrid','City or venue name for an on-site tournament.')])}${section('Admission and visibility','Nothing is preselected: each is your decision for this tournament.',[
field('admission','Admission','Automatic',lock,'select',true),field('checkIn','Check-in','Mandatory','Entries have checked in. Undo every check-in to change it.','select',true),field('visibility','Visibility','Public','Public: listed. Unlisted: readable by link. Private: owner-only access.','select',false,true)])}<div class="actions">${button('Save changes','save','primary')}<a class="button" href="entries-states.html?state=list-with-entries">Back to tournaments</a></div></form></div>`;}

function render(){document.querySelector('#surface').innerHTML=`<div class="fl-shell"><aside class="fl-rail"><a class="brand" href="access-states.html?state=one-organisation">HERALD<span>.</span></a><div class="fl-context"><strong>Northside Gaming</strong><small>Organisation · Owner</small><a href="access-states.html?state=organisation-selector">${icon('switch')}Switch organisation</a></div><nav class="fl-nav" aria-label="Workspace"><a href="access-states.html?state=one-organisation">Overview</a><a href="entries-states.html?state=list-with-entries&kind=team" aria-current="page">Tournaments</a></nav></aside><main id="main" class="fl-page" tabindex="-1"><header class="fl-top"><span>Organiser workspace</span><div class="fl-account">${button('Alex Morgan'+icon('down'),'account','','aria-expanded="false" aria-controls="account-panel"')}<div id="account-panel" class="fl-account-panel" hidden><strong>Alex Morgan</strong><small>Signed in with your account provider</small><a class="button" href="access-states.html?state=one-organisation">Organise</a>${button('Sign out','explain')}</div></div></header><div class="fl-content">${heading()}${config?configuration():entries()}</div></main></div>`;}
document.querySelector('#state-links').innerHTML=states.map(key=>`<a href="?state=${key}" ${key===state?'aria-current="page"':''}>${key.replaceAll('-',' ')}</a>`).join('');
render();
function toast(text){document.querySelector('.check-toasts')?.remove();const t=document.createElement('section');t.className='check-toasts';t.setAttribute('aria-label','Notifications');t.innerHTML=`<div class="check-toast"><svg class="fl-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg><p role="status">${escape(text)}</p>${button('<svg class="fl-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg>','dismiss','','aria-label="Dismiss notification"')}</div>`;document.body.append(t);document.body.style.setProperty('--check-toast-reserve',t.getBoundingClientRect().height+16+'px');}

if(state==='checked-in-toast')toast('Jamie Brook checked in.');
if(state==='undo')toast("Robin Vale's check-in undone.");
function closeDialog(){const d=document.querySelector('dialog');const opener=d?._opener;d?.remove();document.body.classList.remove('has-modal');opener?.focus();}
function dialog(heading,body,trigger){const d=document.createElement('dialog');d.className='fl-modal drawer';d.setAttribute('aria-labelledby','drawer-heading');d.innerHTML=`<h2 id="drawer-heading" tabindex="-1" class="focus-evidence">${heading}</h2>${body}<div class="actions">${button('Back to entries','close')}</div>`;d._opener=trigger;document.body.append(d);d.showModal();d.querySelector('h2').focus();d.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});}
document.addEventListener('submit',e=>{e.preventDefault();toast('Changes saved.');});
document.addEventListener('click',e=>{const control=e.target.closest('[data-action]');if(!control||control.disabled)return;const action=control.dataset.action;
if(action==='account'){const panel=document.querySelector('#account-panel');panel.hidden=!panel.hidden;control.setAttribute('aria-expanded',String(!panel.hidden));return;}
if(action==='dismiss'){document.querySelector('.check-toasts')?.remove();document.body.style.removeProperty('--check-toast-reserve');return;}
if(action==='check'){const i=Number(control.dataset.index);confirmed[i]=!confirmed[i];failure=false;render();toast(confirmed[i]?`${names[i]} checked in.`:`${names[i]}'s check-in undone.`);document.querySelector(`[data-entry="${i}"] [data-action="check"]`).focus();document.querySelector(`[data-entry="${i}"]`).scrollIntoView({block:'center'});return;}
if(action==='reload'){conflict=false;render();document.querySelector('#summary-heading').setAttribute('tabindex','-1');document.querySelector('#summary-heading').focus();return;}
if(action==='close'){closeDialog();return;}
if(action==='add'){dialog(teams?'Add team':'Add player',`<p class="help">Choose a guest of Northside Gaming or create a new ${teams?'team':'player'}.</p><div class="actions">${button('Choose existing','existing')}${button('Create new','new')}</div><div class="fl-field"><label for="guest-name">Search by name</label><input id="guest-name"><p class="help">Only ${teams?'team':'player'} guests in Northside Gaming.</p></div>`,control);return;}
if(action==='existing'||action==='new'){const input=document.querySelector('#guest-name');input.labels[0].textContent=action==='new'?'Name (alias)':'Search by name';input.focus();return;}
if(action==='roster'){const i=Number(control.dataset.index);dialog(`Roster · ${names[i]||'Meadow Foxes'}`,`<p class="help">Admitted team · Saturday Team League</p><p class="readiness">${i===0?'2 of 3–5 players · incomplete':'4 of 3–5 players'}</p><h3>Members</h3><ul class="fl-rows">${(i===0?['Robin Vale','Sam Reed']:['Rowan Lake','Ellis Stone','Quinn Ash','Avery Lane']).map(n=>`<li>${n}</li>`).join('')}</ul>`,control);return;}
if(action==='save'){toast('Changes saved.');return;}
const message=document.createElement('p');message.className='help';message.setAttribute('role','status');message.textContent='This action belongs to the existing entries or registration review. No request is sent.';control.parentElement.append(message);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const panel=document.querySelector('#account-panel');if(panel&&!panel.hidden){panel.hidden=true;document.querySelector('[data-action="account"]').focus();}}});
})();
